def retire_surplus_unfinished(apps, schema_editor):
    """Keep the newest unfinished lesson per learner; abandon the older ones.

    Without this the AddConstraint below fails on any database where a learner
    opened the app on more than one day without finishing -- which is the
    normal case, not the edge case.
    """
    Lesson = apps.get_model("lessons", "Lesson")

    unfinished = (
        Lesson.objects.exclude(status="completed")
        .order_by("user_id", "-date", "-id")
        .values_list("id", "user_id")
    )

    seen_users = set()
    surplus = []
    for lesson_id, user_id in unfinished:
        if user_id in seen_users:
            surplus.append(lesson_id)
        else:
            seen_users.add(user_id)

    # In batches: a long-running learner could have hundreds, and SQLite has a
    # ceiling on how many parameters one statement may carry.
    for start in range(0, len(surplus), 500):
        Lesson.objects.filter(id__in=surplus[start : start + 500]).update(status="abandoned")


